UPDATE t_p79235343_uplink_clone_website.cms_service_faq SET question = 'Какое сетевое оборудование вы обслуживаете?', answer = 'Работаем с оборудованием различных производителей — выбираем под бюджет и задачи. Можем работать с уже имеющимся оборудованием или подобрать новое с учётом перспективы масштабирования.' WHERE id = 17;

UPDATE t_p79235343_uplink_clone_website.cms_service_faq SET question = 'Какая категория кабеля нужна?', answer = 'Для офиса достаточно витой пары категорий Cat5e (до 1 Гбит/с) или Cat6 (до 10 Гбит/с). Для линий между этажами или зданиями подбираем подходящее решение исходя из расстояния и требований к скорости.' WHERE id = 11;

UPDATE t_p79235343_uplink_clone_website.cms_service_faq SET question = 'Делаете ли тестирование сети?', answer = 'Да, тестируем каждую линию профессиональным оборудованием после монтажа и оформляем протокол. Это гарантия качества выполненных работ.' WHERE id = 12;

UPDATE t_p79235343_uplink_clone_website.cms_service_faq SET question = 'Можно ли подключить дополнительные сервисы?', answer = 'Да, после запуска телефонии можно подключить запись разговоров, статистику, голосовое меню, переадресацию и другие функции в зависимости от задач компании.' WHERE id = 13;